import { randomBytes } from 'node:crypto';

/**
 * Login handles of supervised teens (Phase 3a, FP3-09).
 *
 * `{slug of the first name, up to 20}-{8 Crockford base32 chars}`: readable
 * prefix, 40 bits of random suffix. Lowercase letters, digits and '-', 10 to 29
 * characters (the DB CHECK allows 6 to 40). Always generated by the server; no
 * client ever supplies one. A handle has no '@', so it can never equal an
 * email address.
 */
export const LOGIN_HANDLE_PATTERN = /^[a-z0-9][a-z0-9-]{5,39}$/;

/** Crockford base32 without I, L, O, U (lowercase): readable when dictated. */
const ALPHABET = '0123456789abcdefghjkmnpqrstvwxyz';
const SUFFIX_LENGTH = 8;
const SLUG_MAX_LENGTH = 20;
const SLUG_FALLBACK = 'teen';

/** Source of random bytes; injectable so tests can be deterministic. */
export type RandomBytes = (size: number) => Uint8Array;

export function isValidLoginHandle(value: string): boolean {
  return LOGIN_HANDLE_PATTERN.test(value);
}

/**
 * The first name as a handle prefix: accents removed, lowercase, only a-z and
 * 0-9, cut to 20 characters. An empty result falls back to "teen".
 */
export function slugifyFirstName(name: string | null | undefined): string {
  const first = (name ?? '').trim().split(/\s+/)[0] ?? '';
  const slug = first
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '')
    .slice(0, SLUG_MAX_LENGTH);
  return slug.length > 0 ? slug : SLUG_FALLBACK;
}

/** 8 characters = 40 bits, drawn from 5 random bytes. */
export function randomHandleSuffix(
  random: RandomBytes = (size) => randomBytes(size),
): string {
  const bytes = random(5);
  let bits = 0n;
  for (const byte of bytes) {
    bits = (bits << 8n) | BigInt(byte);
  }
  let suffix = '';
  for (let i = SUFFIX_LENGTH - 1; i >= 0; i -= 1) {
    suffix += ALPHABET[Number((bits >> BigInt(i * 5)) & 31n)];
  }
  return suffix;
}

export function generateLoginHandle(
  firstName: string | null | undefined,
  random: RandomBytes = (size) => randomBytes(size),
): string {
  return `${slugifyFirstName(firstName)}-${randomHandleSuffix(random)}`;
}

/**
 * Generates a handle that `isTaken` does not know. A collision is regenerated,
 * never surfaced as an error. Callers must STILL be ready for the unique index
 * to reject a concurrent winner (see {@link isUniqueViolation}) and call this
 * again.
 */
export async function allocateLoginHandle(
  firstName: string | null | undefined,
  isTaken: (handle: string) => Promise<boolean>,
  options: { attempts?: number; random?: RandomBytes } = {},
): Promise<string> {
  const attempts = options.attempts ?? 5;
  for (let attempt = 0; attempt < attempts; attempt += 1) {
    const handle = generateLoginHandle(firstName, options.random);
    if (!(await isTaken(handle))) return handle;
  }
  // 40 bits of entropy make this practically unreachable.
  throw new Error('could not allocate a unique login handle');
}

/** A Prisma P2002 (unique constraint) error. */
export function isUniqueViolation(error: unknown): boolean {
  return (
    typeof error === 'object' &&
    error !== null &&
    (error as { code?: unknown }).code === 'P2002'
  );
}
